        // After withdrawal, the contract must still exist.
        // owner() should return the original owner (address(this)).
        bool ok;
        try c.owner() returns (address currentOwner) {
            ok = (currentOwner == address(this));
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

